from pathlib import Path

index_path=Path('index.html')
css_path=Path('style.css')
js_path=Path('script.js')
sw_path=Path('sw.js')

html=index_path.read_text(encoding='utf-8')
css=css_path.read_text(encoding='utf-8')
js=js_path.read_text(encoding='utf-8')
sw=sw_path.read_text(encoding='utf-8')

# --- HTML: camera ao vivo, navegação mobile e nomenclatura de detalhes ---
html=html.replace('<button class="mobile-nav-btn active" type="button"><span>▦</span><small>Fichário</small></button>', '<button id="btnMobileBinder" class="mobile-nav-btn active" type="button"><span>▦</span><small>Fichário</small></button>')
html=html.replace('<label class="camera-compact"><input id="cardPhoto" type="file" accept="image/*" capture="environment"><span>⌁</span><b>Câmera</b></label>\n        <button id="btnUsePhotoHints" class="mini-btn" type="button">Ler foto</button>', '<button id="btnLiveScan" class="camera-compact" type="button"><span>⌁</span><b>Escanear</b></button>\n        <label class="camera-compact gallery-compact"><input id="cardPhoto" type="file" accept="image/*"><span>▧</span><b>Galeria</b></label>\n        <button id="btnUsePhotoHints" class="mini-btn hidden" type="button">Ler foto</button>')
html=html.replace('Ver carta 3D','Detalhes da carta')
html=html.replace('Mova o mouse para inclinar · duplo clique para virar','Arraste sobre a carta para inclinar · toque duas vezes para virar')

scanner='''\n  <dialog id="scanDialog" class="sheet-dialog live-scan-dialog">\n    <div class="dialog-shell live-scan-shell">\n      <div class="scan-topbar">\n        <div><p class="kicker">Scanner ao vivo</p><h2>Enquadre a carta</h2></div>\n        <button id="btnCloseLiveScan" class="icon-only" type="button">×</button>\n      </div>\n      <div class="live-camera-stage">\n        <video id="scanVideo" autoplay playsinline muted></video>\n        <canvas id="scanCanvas" class="hidden"></canvas>\n        <div class="scan-vignette"></div>\n        <div class="scan-card-frame"><span></span></div>\n        <div class="scan-pulse"></div>\n      </div>\n      <div class="scan-footer">\n        <div><strong id="scanLiveStatus">Abrindo câmera...</strong><small>Mantenha a carta inteira dentro da moldura. A leitura acontece automaticamente.</small></div>\n        <button id="btnScanManual" class="btn btn-secondary" type="button">Busca manual</button>\n      </div>\n    </div>\n  </dialog>\n'''
if 'id="scanDialog"' not in html:
    html=html.replace('  <dialog id="cardDialog"', scanner+'\n  <dialog id="cardDialog"')
index_path.write_text(html,encoding='utf-8')

# --- CSS V6 ---
marker='/* ===== V6 MOBILE/SCANNER/DETAILS ===== */'
if marker not in css:
    css += r'''\n\n/* ===== V6 MOBILE/SCANNER/DETAILS ===== */\n.binder-toolbar{position:relative;z-index:8;grid-template-columns:42px minmax(0,1fr) 42px;overflow:visible}\n.binder-toolbar .round-btn{width:32px;height:32px;display:grid;place-items:center;justify-self:center;padding:0;line-height:1;font-size:23px;border-radius:50%}\n.binder-toolbar .round-btn:disabled{opacity:.28}\n.page-center{min-width:0}\n.page-label{white-space:nowrap}\n\n/* detalhes da carta: estável e responsivo */\n.card-inspector-dialog{width:min(980px,calc(100vw - 28px))}\n.inspector-shell{display:grid;grid-template-columns:minmax(280px,.86fr) minmax(390px,1.14fr);gap:0;max-height:min(90dvh,860px);overflow:hidden;padding:0!important}\n.card-showcase{min-height:0;padding:28px;display:grid;place-items:center;align-content:center;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 44%,rgba(74,167,255,.16),transparent 36%),linear-gradient(145deg,#0a0e15,#151b25 58%,#0b0e13)}\n.card-details-panel{min-width:0;overflow:auto;padding:26px 24px 24px;background:#15191d}\n.card-3d{width:min(250px,76%);aspect-ratio:63/88;perspective:1100px;touch-action:none;user-select:none;cursor:grab;position:relative;z-index:3}\n.card-3d:active{cursor:grabbing}\n.card-3d-inner{width:100%;height:100%;position:relative;transform-style:preserve-3d;will-change:transform;transition:transform .12s ease-out}\n.card-face{position:absolute;inset:0;backface-visibility:hidden;border-radius:14px;overflow:hidden;box-shadow:0 26px 60px rgba(0,0,0,.48)}\n.card-front img{width:100%;height:100%;object-fit:contain;display:block}\n.card-back{transform:rotateY(180deg)}\n.card-3d.flipped .card-3d-inner{transform:rotateY(180deg)!important}\n.showcase-help{margin:14px 0 0;color:#8e98a3;font-size:10px;text-align:center}\n\n/* scanner ao vivo */\n.live-scan-dialog{width:min(760px,calc(100vw - 18px));max-width:none}\n.live-scan-shell{padding:0!important;overflow:hidden;max-height:min(94dvh,900px);background:#080b0e}\n.scan-topbar{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 16px;border-bottom:1px solid var(--line);background:#11151a}\n.scan-topbar h2{margin:0;font-size:19px}\n.live-camera-stage{position:relative;width:100%;height:min(68dvh,640px);overflow:hidden;background:#020304}\n#scanVideo{width:100%;height:100%;object-fit:cover;display:block}\n.scan-vignette{position:absolute;inset:0;box-shadow:inset 0 0 0 100vmax rgba(0,0,0,.40);clip-path:polygon(0 0,100% 0,100% 100%,0 100%,0 0,18% 12%,18% 88%,82% 88%,82% 12%,18% 12%);pointer-events:none}\n.scan-card-frame{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);height:76%;aspect-ratio:63/88;border:2px solid rgba(255,255,255,.82);border-radius:18px;box-shadow:0 0 0 1px rgba(0,0,0,.35),0 0 34px rgba(50,215,160,.10);pointer-events:none}\n.scan-card-frame:before,.scan-card-frame:after,.scan-card-frame span:before,.scan-card-frame span:after{content:"";position:absolute;width:26px;height:26px;border-color:var(--green);border-style:solid}\n.scan-card-frame:before{left:-3px;top:-3px;border-width:3px 0 0 3px;border-radius:12px 0 0 0}\n.scan-card-frame:after{right:-3px;top:-3px;border-width:3px 3px 0 0;border-radius:0 12px 0 0}\n.scan-card-frame span:before{left:-3px;bottom:-3px;border-width:0 0 3px 3px;border-radius:0 0 0 12px}\n.scan-card-frame span:after{right:-3px;bottom:-3px;border-width:0 3px 3px 0;border-radius:0 0 12px 0}\n.scan-pulse{position:absolute;left:20%;right:20%;top:50%;height:2px;background:linear-gradient(90deg,transparent,var(--green),transparent);box-shadow:0 0 16px var(--green);animation:scanline 1.7s ease-in-out infinite;pointer-events:none}\n@keyframes scanline{0%,100%{transform:translateY(-22dvh);opacity:.2}50%{transform:translateY(22dvh);opacity:1}}\n.scan-footer{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:13px 16px;background:#11151a}\n.scan-footer strong,.scan-footer small{display:block}.scan-footer small{margin-top:3px;color:var(--muted);font-size:10px}\n\n/* adicionador mobile nunca ultrapassa a tela */\n@media(max-width:820px){\n  .app{height:100dvh;overflow:hidden}\n  .workspace{height:calc(100dvh - 62px - 68px - env(safe-area-inset-bottom));overflow:hidden}\n  .binder-area{height:100%;display:grid;grid-template-rows:48px minmax(0,1fr);overflow:hidden}\n  .binder-toolbar{height:48px!important;min-height:48px;position:relative!important;top:auto!important;left:auto!important;right:auto!important;padding:6px 10px;z-index:12;background:#0d1013}\n  .binder-toolbar .round-btn{width:34px;height:34px;font-size:24px}\n  .binder-stage{height:auto!important;min-height:0!important;padding:8px 8px 10px!important;overflow:hidden!important;display:grid!important;place-items:center!important}\n  .binder-spread{height:100%!important;width:100%!important;display:grid!important;place-items:center!important;margin:0!important}\n  .binder-sheet-wrap{height:min(100%,calc((100vw - 16px)/.72))!important;width:auto!important;max-width:100%!important;aspect-ratio:.72/1;margin:0 auto!important}\n  .binder-sheet{width:100%!important;height:100%!important;aspect-ratio:auto!important}\n  .summary-panel{inset:62px 0 calc(68px + env(safe-area-inset-bottom)) 0!important;height:auto!important;z-index:42}\n  .mobile-nav-btn.active{color:var(--accent2)!important}\n\n  .catalog-dialog,.card-inspector-dialog,.live-scan-dialog{width:100vw!important;height:100dvh!important;max-height:none!important;margin:0!important;padding:0!important}\n  .catalog-shell,.inspector-shell,.live-scan-shell{position:fixed!important;inset:0!important;width:100vw!important;height:100dvh!important;max-height:none!important;border:0!important;border-radius:0!important}\n  .catalog-shell{display:flex!important;flex-direction:column!important;padding:0 12px calc(82px + env(safe-area-inset-bottom))!important;overflow:hidden!important}\n  .catalog-head{flex:0 0 auto;margin:0 -12px 10px!important;top:0!important;padding:12px 14px!important}\n  .catalog-toolbar{flex:0 0 auto;display:grid!important;grid-template-columns:minmax(0,1fr) auto auto!important;gap:7px!important}\n  .search-big-wrap{grid-column:1/-1}\n  .camera-compact{min-height:42px!important;padding:8px 10px!important;white-space:nowrap}\n  .catalog-filters{flex:0 0 auto;display:grid!important;grid-template-columns:1fr 1fr!important;gap:7px!important}\n  .catalog-filters .btn{grid-column:1/-1}\n  #searchStatus,#ocrStatus{flex:0 0 auto;margin:4px 0!important}\n  .catalog-grid{flex:1 1 auto!important;min-height:0!important;overflow:auto!important;display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important;padding-bottom:12px!important}\n  .selection-tray{position:absolute!important;left:0!important;right:0!important;bottom:0!important;z-index:15;display:grid!important;grid-template-columns:1fr auto auto!important;gap:7px!important;padding:9px 10px calc(9px + env(safe-area-inset-bottom))!important;background:rgba(15,18,21,.98)!important;border-top:1px solid var(--line)!important}\n  .selection-tray small{display:none!important}\n\n  .inspector-shell{display:block!important;overflow:auto!important;background:#11151a}\n  .card-showcase{min-height:42svh!important;padding:18px 14px!important}\n  .card-details-panel{overflow:visible!important;padding:18px 14px calc(32px + env(safe-area-inset-bottom))!important}\n  .card-3d{width:min(190px,58vw)!important}\n  .showcase-help{font-size:9px}\n\n  .live-scan-shell{display:flex;flex-direction:column}\n  .live-camera-stage{flex:1 1 auto;height:auto;min-height:0}\n  .scan-card-frame{height:min(72%,66vw/.716)}\n  .scan-footer{flex:0 0 auto;padding-bottom:calc(12px + env(safe-area-inset-bottom))}\n}\n'''
    css_path.write_text(css,encoding='utf-8')

# --- JS V6 ---
js_marker='// ===== V6 MOBILE UX + LIVE SCAN + DETAILS ====='
if js_marker not in js:
    js += r'''\n\n// ===== V6 MOBILE UX + LIVE SCAN + DETAILS =====\nlet liveScanStream=null,liveScanTimer=null,liveScanBusy=false;\nlet mobileHoldDrag=null;\n\nfunction setMobileView(view){\n  const panel=$('summaryPanel'),binderBtn=$('btnMobileBinder'),summaryBtn=$('btnMobileSummary');\n  const summary=view==='summary';\n  panel?.classList.toggle('mobile-open',summary);\n  binderBtn?.classList.toggle('active',!summary);\n  summaryBtn?.classList.toggle('active',summary);\n}\n\nfunction stopLiveScan(){\n  clearTimeout(liveScanTimer);liveScanTimer=null;liveScanBusy=false;\n  if(liveScanStream){liveScanStream.getTracks().forEach(t=>t.stop());liveScanStream=null}\n  const v=$('scanVideo');if(v)v.srcObject=null;\n}\n\nasync function startLiveScan(){\n  try{\n    pendingPosition=pendingPosition||freePositions(currentPage,1)[0];\n    openDialog('scanDialog');\n    $('scanLiveStatus').textContent='Abrindo câmera...';\n    stopLiveScan();\n    liveScanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:1920}},audio:false});\n    const v=$('scanVideo');v.srcObject=liveScanStream;await v.play();\n    $('scanLiveStatus').textContent='Câmera ativa · procurando carta...';\n    liveScanTimer=setTimeout(scanLiveFrame,900);\n  }catch(e){\n    console.error(e);\n    $('scanLiveStatus').textContent='Não consegui abrir a câmera. Verifique a permissão do navegador.';\n  }\n}\n\nfunction parseScanText(t){\n  const clean=String(t||'');\n  const num=clean.match(/(\\d{1,4})\\s*\\/\\s*(\\d{1,4})/);\n  const lines=clean.split(/\\n+/).map(v=>v.replace(/[^\\p{L}\\p{N}\\s.'-]/gu,' ').replace(/\\s+/g,' ').trim()).filter(v=>v.length>=3&&v.length<=42);\n  const bad=/^(basico|basic|stage|estagio|hp|habilidade|ability|trainer|treinador|fraqueza|resistencia|recuo|weakness|resistance|retreat)/i;\n  const name=lines.find(v=>!bad.test(v)&&/[A-Za-zÀ-ÿ]{3}/.test(v)&&!/^\\d+$/.test(v))||'';\n  return{name:name.replace(/\\bHP\\s*\\d+.*/i,'').trim(),number:num?`${num[1]}/${num[2]}`:''};\n}\n\nasync function scanLiveFrame(){\n  if(!liveScanStream||liveScanBusy)return;\n  liveScanBusy=true;\n  try{\n    const video=$('scanVideo'),canvas=$('scanCanvas');\n    if(!video?.videoWidth){liveScanTimer=setTimeout(scanLiveFrame,700);return}\n    const vw=video.videoWidth,vh=video.videoHeight;\n    const cropH=Math.floor(vh*.78),cropW=Math.min(Math.floor(cropH*63/88),Math.floor(vw*.72));\n    const sx=Math.floor((vw-cropW)/2),sy=Math.floor((vh-cropH)/2);\n    canvas.width=Math.max(420,cropW);canvas.height=Math.max(590,cropH);\n    canvas.getContext('2d',{willReadFrequently:true}).drawImage(video,sx,sy,cropW,cropH,0,0,canvas.width,canvas.height);\n    $('scanLiveStatus').textContent='Analisando automaticamente...';\n    if(!await ensureOCR())throw new Error('ocr');\n    const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.86));\n    const r=await Tesseract.recognize(blob,'por+eng');\n    const hint=parseScanText(r?.data?.text||'');\n    if(hint.name||hint.number){\n      stopLiveScan();closeDialog('scanDialog');\n      openAddForPosition(pendingPosition?.page||currentPage,pendingPosition?.slot);\n      if(hint.name)$('searchName').value=hint.name;\n      if(hint.number)$('searchNumber').value=hint.number;\n      $('ocrStatus').textContent=`Scanner leu: ${[hint.name,hint.number].filter(Boolean).join(' · ')}`;\n      await searchCards();\n      return;\n    }\n    $('scanLiveStatus').textContent='Ainda procurando · ajuste o enquadramento';\n  }catch(e){\n    console.warn('live scan',e);\n    $('scanLiveStatus').textContent='Ainda procurando · mantenha a carta parada';\n  }finally{\n    liveScanBusy=false;\n    if(liveScanStream)liveScanTimer=setTimeout(scanLiveFrame,1100);\n  }\n}\n\nfunction setup3d(){\n  const el=$('card3d'),inner=el?.querySelector('.card-3d-inner');if(!el||!inner)return;\n  let raf=0,targetX=0,targetY=0,drag=false,lastTap=0;\n  const paint=()=>{raf=0;if(el.classList.contains('flipped'))return;inner.style.transform=`rotateY(${targetX}deg) rotateX(${targetY}deg)`};\n  const update=(clientX,clientY)=>{const r=el.getBoundingClientRect();const x=Math.max(-.5,Math.min(.5,(clientX-r.left)/r.width-.5));const y=Math.max(-.5,Math.min(.5,(clientY-r.top)/r.height-.5));targetX=x*20;targetY=-y*20;if(!raf)raf=requestAnimationFrame(paint)};\n  el.addEventListener('pointerdown',e=>{drag=true;el.setPointerCapture?.(e.pointerId);update(e.clientX,e.clientY);const now=Date.now();if(now-lastTap<330){el.classList.toggle('flipped');inner.style.transform=el.classList.contains('flipped')?'rotateY(180deg)':'rotateY(0deg) rotateX(0deg)'}lastTap=now});\n  el.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||drag){e.preventDefault();update(e.clientX,e.clientY)}} ,{passive:false});\n  const end=()=>{drag=false;if(!el.classList.contains('flipped')){targetX=0;targetY=0;if(!raf)raf=requestAnimationFrame(paint)}};\n  el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')end()});\n  el.addEventListener('dblclick',()=>{el.classList.toggle('flipped');inner.style.transform=el.classList.contains('flipped')?'rotateY(180deg)':'rotateY(0deg) rotateX(0deg)'});\n}\n\nfunction installMobileHoldDrag(){\n  const clear=()=>{if(!mobileHoldDrag)return;clearTimeout(mobileHoldDrag.timer);mobileHoldDrag.ghost?.remove();mobileHoldDrag.card?.classList.remove('dragging');document.querySelectorAll('.binder-pocket.drag-over').forEach(p=>p.classList.remove('drag-over'));mobileHoldDrag=null};\n  document.addEventListener('pointerdown',e=>{\n    if(e.pointerType==='mouse')return;const card=e.target.closest('.pocket-card');if(!card)return;\n    const state={card,id:card.dataset.id,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,active:false,ghost:null};\n    state.timer=setTimeout(()=>{\n      state.active=true;hideContext();\n      try{card.dispatchEvent(new PointerEvent('pointermove',{pointerId:e.pointerId,pointerType:e.pointerType,bubbles:true,clientX:e.clientX+1,clientY:e.clientY+1}))}catch{}\n      const g=card.cloneNode(true);g.className='mobile-drag-ghost';g.style.width=`${card.getBoundingClientRect().width}px`;g.style.height=`${card.getBoundingClientRect().height}px`;g.style.left=`${e.clientX}px`;g.style.top=`${e.clientY}px`;document.body.appendChild(g);state.ghost=g;card.classList.add('dragging');navigator.vibrate?.(25);\n    },230);\n    mobileHoldDrag=state;\n  },true);\n  document.addEventListener('pointermove',e=>{\n    const s=mobileHoldDrag;if(!s||s.pointerId!==e.pointerId)return;\n    if(!s.active){if(Math.hypot(e.clientX-s.startX,e.clientY-s.startY)>12)clearTimeout(s.timer);return}\n    e.preventDefault();e.stopPropagation();\n    if(s.ghost){s.ghost.style.left=`${e.clientX}px`;s.ghost.style.top=`${e.clientY}px`}\n    document.querySelectorAll('.binder-pocket.drag-over').forEach(p=>p.classList.remove('drag-over'));\n    document.elementFromPoint(e.clientX,e.clientY)?.closest('.binder-pocket')?.classList.add('drag-over');\n  },{capture:true,passive:false});\n  document.addEventListener('pointerup',e=>{\n    const s=mobileHoldDrag;if(!s||s.pointerId!==e.pointerId)return;clearTimeout(s.timer);\n    if(s.active){e.preventDefault();e.stopPropagation();const p=document.elementFromPoint(e.clientX,e.clientY)?.closest('.binder-pocket');const source=collection.find(c=>String(c.id)===String(s.id));if(source&&p)moveCard(source,+p.dataset.page,+p.dataset.slot)}\n    clear();\n  },true);\n  document.addEventListener('pointercancel',clear,true);\n}\n\nfunction setupV6Controls(){\n  const binderBtn=$('btnMobileBinder'),summaryBtn=$('btnMobileSummary'),closeSummary=$('btnCloseSummary');\n  if(binderBtn)binderBtn.onclick=()=>setMobileView('binder');\n  if(summaryBtn)summaryBtn.onclick=()=>setMobileView('summary');\n  if(closeSummary)closeSummary.onclick=()=>setMobileView('binder');\n  if($('btnLiveScan'))$('btnLiveScan').onclick=startLiveScan;\n  if($('btnCloseLiveScan'))$('btnCloseLiveScan').onclick=()=>{stopLiveScan();closeDialog('scanDialog')};\n  if($('btnScanManual'))$('btnScanManual').onclick=()=>{stopLiveScan();closeDialog('scanDialog');openAddForPosition(pendingPosition?.page||currentPage,pendingPosition?.slot)};\n  if($('btnMobileScan'))$('btnMobileScan').onclick=()=>{pendingPosition=freePositions(currentPage,1)[0];startLiveScan()};\n  if($('cardPhoto'))$('cardPhoto').onchange=async()=>{if($('cardPhoto').files?.[0])await usePhotoHints()};\n  $('scanDialog')?.addEventListener('close',stopLiveScan);\n  installMobileHoldDrag();\n}\n\ndocument.addEventListener('DOMContentLoaded',setupV6Controls);\n'''
    js_path.write_text(js,encoding='utf-8')

sw=sw.replace("pokemon-binder-v5","pokemon-binder-v6").replace("pokemon-binder-v4","pokemon-binder-v6")
sw_path.write_text(sw,encoding='utf-8')
